(function() {
  const banner = document.getElementById('cookieBanner');
  const settingsPanel = document.getElementById('cookieSettingsPanel');
  const saved = localStorage.getItem('cookieConsent');

  if (saved) {
    banner.classList.add('hidden');
    if (saved === 'declined') {
      // nothing loaded
    }
  }

  document.getElementById('cookieAccept').addEventListener('click', () => {
    localStorage.setItem('cookieConsent', 'accepted');
    banner.classList.add('hidden');
  });

  document.getElementById('cookieDecline').addEventListener('click', () => {
    localStorage.setItem('cookieConsent', 'declined');
    banner.classList.add('hidden');
  });

  document.getElementById('cookieSettings').addEventListener('click', () => {
    banner.classList.add('hidden');
    settingsPanel.classList.add('open');
  });

  document.getElementById('cookieSettingsLink').addEventListener('click', (e) => {
    e.preventDefault();
    settingsPanel.classList.add('open');
  });

  document.getElementById('cookieCancelSettings').addEventListener('click', () => {
    settingsPanel.classList.remove('open');
    banner.classList.remove('hidden');
  });

  document.getElementById('cookieSaveSettings').addEventListener('click', () => {
    localStorage.setItem('cookieConsent', 'custom');
    settingsPanel.classList.remove('open');
  });
})();

